// Üretilen dosya: tool/ozgun/uret.py. Spor · Cimnastik, eskrim, okçuluk ve atıcılık disiplinleri (artistik ve ritmik cimnastik aletleri, flöre-epe-kılıç farkları, olimpik yay, puanlama) (orta).
const ozSport16Orta = <(String, String, List<String>, String)>[
  ('Uluslararası Cimnastik Federasyonu puanlama sisteminde bir serinin toplam puanını oluşturan D ve E bileşenleri sırasıyla neyi ifade eder?', 'Zorluk derecesi ve uygulama kalitesi', ['Dayanıklılık süresi ve esneklik açısı', 'Denge katsayısı ve estetik uyum', 'Dönüş adedi ve ekleme bonusu'], 'Modern cimnastik puanlamasında D (Difficulty) yapılan hareketlerin zorluk değerini, E (Execution) ise 10 üzerinden yapılan teknik kesintiler sonrası uygulama puanını gösterir.'),
  ('Halka aletinde sporcunun kollarını iki yana tam yatay açarak gövdesini dik ve hareketsiz tuttuğu ünlü statik kuvvet duruşuna ne ad verilir?', 'Demir haç duruşu', ['Thomas salınımı', 'Tkatchev geçişi', 'Yurchenko sıçrayışı'], 'Demir haç (Iron Cross), halka aletinde kollar yere paralel açıkken omuz ve göğüs kaslarıyla en az iki saniye korunan temel güç duruşudur.'),
